target.css:
:root {
  --ink: #17343a;
  --muted: #668087;
  --paper: #fffdf5;
  --line: #d7e5df;
  --seafoam: #dff2e9;
  --teal: #187a72;
  --coral: #f06c5d;
  --coral-pale: #fff0e8;
  --sand: #f4e5bd;
}

* {
  box-sizing: border-box;
}

.survey-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.survey-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  background: var(--seafoam);
  border-bottom: 1px solid var(--line);
}

h2,
p {
  margin: 0;
}

.eyebrow,
.detail > span,
.checklist-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.09em;
}

h2 {
  margin-top: 4px;
  font-size: 22px;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.tide-badge {
  padding: 6px 9px;
  color: var(--coral);
  background: var(--coral-pale);
  border: 1px solid var(--coral);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.shift-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 13px 18px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: 12px;
  border-left: 1px solid var(--line);
}

.detail:first-child {
  padding-left: 0;
  border-left: 0;
}

.detail strong {
  font-size: 16px;
  line-height: 1.1;
}

.detail small {
  color: var(--muted);
  font-size: 11px;
}

.checklist {
  margin: 0 18px;
  padding: 10px 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.checklist-label {
  margin-bottom: 7px;
}

ul {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.check-dot {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  color: var(--paper);
  background: var(--teal);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.check-dot.pending {
  color: var(--ink);
  background: var(--sand);
}

.survey-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px 14px;
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

